def roman_to_int(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("Input must be a non-empty string")

    # Canonical Roman numeral values
    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    # Valid subtractive pairs
    subtractive = {
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90,
        'CD': 400, 'CM': 900
    }

    # Validate characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"Invalid character: {ch}")

    # Validate no more than 3 consecutive identical symbols (except M)
    # and no invalid repetitions
    for i in range(len(s)):
        if i >= 3 and s[i] == s[i-1] == s[i-2] == s[i-3]:
            raise ValueError(f"Invalid repetition: {s[i]} cannot appear 4 times consecutively")
        if s[i] in ('V', 'L', 'D') and i > 0 and s[i] == s[i-1]:
            raise ValueError(f"Invalid repetition: {s[i]} cannot be repeated")

    total = 0
    i = 0
    while i < len(s):
        # Check for subtractive pair
        if i + 1 < len(s) and s[i:i+2] in subtractive:
            pair = s[i:i+2]
            # Validate subtractive pair is not preceded by same value or smaller
            if i > 0:
                prev_val = values[s[i-1]]
                pair_val = subtractive[pair]
                if prev_val <= pair_val:
                    raise ValueError(f"Invalid order: {pair} cannot follow {s[i-1]}")
            total += subtractive[pair]
            i += 2
        else:
            # Single character
            if i > 0:
                prev_val = values[s[i-1]]
                curr_val = values[s[i]]
                if prev_val < curr_val:
                    raise ValueError(f"Invalid order: {s[i]} cannot follow {s[i-1]}")
            total += values[s[i]]
            i += 1

    # Validate range
    if total < 1 or total > 3999:
        raise ValueError(f"Value {total} out of range (1-3999)")

    # Final validation: ensure canonical by converting back and comparing
    if int_to_roman(total) != s:
        raise ValueError(f"Non-canonical Roman numeral: {s}")

    return total


def int_to_roman(n: int) -> str:
    """Helper to generate canonical Roman numeral for validation."""
    if not 1 <= n <= 3999:
        raise ValueError("Out of range")
    result = []
    for value, symbol in [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]:
        count, n = divmod(n, value)
        result.append(symbol * count)
    return ''.join(result)
